'use strict';
const E=window.LT_EVIDENCE;
const tests=[
{id:'launch',title:'Launch & passthrough',steps:'Open Living Table on Quest 3. Complete any permission prompts.',criteria:'The app stays open, the real room is visible, and placement instructions can be read.'},
{id:'placement',title:'Calibrate the tabletop',steps:'Pinch at the center of the physical table, at surface height. Release, move your head, and look back.',criteria:'One horizontal board appears at the intended location, stays aligned, and reports saved or session-only status accurately.'},
{id:'hands',title:'Left & right hand selection',steps:'With each hand separately, pinch above a piece, release, then select a different piece.',criteria:'Both hands select the intended piece once per pinch. Tracking loss does not cause an unintended selection.'},
{id:'movement',title:'Move a piece',steps:'Pinch a piece and then an empty square. Try another move while the animation runs.',criteria:'The piece jumps to the chosen cell, lands with a pulse, and increments the move count once. Concurrent moves are rejected.'},
{id:'controls',title:'Switch layouts & reset',steps:'Use NEXT GAME to cycle both layouts. Move a piece, then RESET, including during its jump.',criteria:'Sandbox shows 8 pieces and Constellation Garden shows 6. Reset restores the selected layout without leftover animation.'},
{id:'restore',title:'Restore after relaunch',steps:'Place and save the board. Quit the app completely, relaunch in the same room, and look around.',criteria:'The board returns to the saved physical position. Piece positions resetting is expected; only the anchor is persisted.'},
{id:'relocate',title:'Move the table & retry saving',steps:'Use MOVE TABLE and pinch at a new table center. If a save fails, try MOVE TABLE again.',criteria:'The prior table is removed, a new placement works, and a session-only anchor does not prevent retrying.'},
{id:'readability',title:'Readability & comfortable interaction',steps:'Read instructions and labels at a natural table distance. Play for several minutes and inspect the edges and controls.',criteria:'Labels are legible, controls are reachable, and there are no obvious visual glitches, crashes, or disruptive stutters. This is a qualitative check, not an FPS benchmark.'}
];
const labels={'pass':'Passed','fail':'Failed','blocked':'Blocked','not-run':'Not run'};
const key='living-table-tests-v1';let events=[];let storageWorks=true;let activeTest=null;
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function date(s){return new Date(s).toLocaleString('en-US',{timeZone:'America/Chicago',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'})+' CT'}
function notice(message){$('notice').hidden=false;$('notice').textContent=message;}
function validEvent(x){return x&&typeof x.id==='string'&&x.id.length<=100&&tests.some(t=>t.id===x.test)&&Object.hasOwn(labels,x.status)&&typeof x.note==='string'&&x.note.trim().length>0&&x.note.length<=3000&&typeof x.device==='string'&&x.device.trim().length>0&&x.device.length<=100&&typeof x.hash==='string'&&/^[a-f0-9]{64}$/i.test(x.hash)&&typeof x.at==='string'&&Number.isFinite(Date.parse(x.at));}
try{let raw=localStorage.getItem(key);if(raw){let data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(validEvent))throw Error('Invalid saved log');events=data;}}catch(error){storageWorks=false;notice('Saved test data could not be read. This session is temporary; export your log before closing. Existing browser data has not been overwritten.');}
function latest(id){return events.filter(x=>x.test===id&&x.hash.toLowerCase()===E.build.sha256.toLowerCase()).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0]}
function pill(status){return `<span class="pill ${status==='pass'?'green':status==='fail'?'red':status==='blocked'?'amber':''}">${labels[status]}</span>`}
function save(){if(!storageWorks)return;try{localStorage.setItem(key,JSON.stringify(events));}catch(error){storageWorks=false;notice('Browser storage is unavailable or full. Your results are in memory; export the log now to keep them.');}}
function summary(){let counts={pass:0,fail:0,blocked:0,'not-run':0};tests.forEach(t=>counts[latest(t.id)?.status||'not-run']++);return counts}
function render(){const counts=summary();$('test-count').textContent=`${counts.pass} / ${tests.length}`;$('test-summary').textContent=`${counts['not-run']} not run · ${counts.fail} failed · ${counts.blocked} blocked`;$('coverage').textContent=`${counts.pass} of ${tests.length} acceptance checks passed`;$('coverage-bar').value=counts.pass;
if(counts.fail){$('gate-title').textContent='Headset issues need attention';$('gate-description').textContent=`${counts.fail} failed check${counts.fail===1?'':'s'} recorded. Fix and retest before calling the headset experience verified.`}
else if(counts.pass===tests.length){$('gate-title').textContent='Headset checklist passed';$('gate-description').textContent='All eight checks have a passing observation for this APK. These are manually reported results, not an automated release certification.'}
else{$('gate-title').textContent='Headset acceptance pending';$('gate-description').textContent=`${counts.pass} of ${tests.length} checks passed. Remaining headset behavior still needs recorded observations.`}
const gateItems=[['Implemented','Quest and desktop scenes, two layouts, animated pieces, and anchor controls.',true],['Desktop checked','Real Unity Play Mode smoke test passed.',E.smoke.passed&&E.smoke.newerThanRuntime],['APK verified',E.verificationCurrent!==false?'Android build succeeded; ARM64 and signature verified for this fingerprint.':'New APK: verify the signature and architecture again.',E.build.result==='Succeeded'&&E.build.newerThanRuntime&&E.verificationCurrent!==false],['Installed',E.installCurrent!==false?'ADB returned Success on Quest 3. Gameplay is a separate gate.':'A prior APK was installed. This APK requires a new installation check.',E.installCurrent!==false],['Headset accepted',`${counts.pass} / ${tests.length} checks passed. Written observations required.`,counts.pass===tests.length]];
$('milestones').textContent=`${gateItems.slice(0,4).filter(x=>x[2]).length} / 4`;
$('delivery').innerHTML=gateItems.map((g,i)=>`<li><span class="step-number">${String(i+1).padStart(2,'0')}</span><div class="step-content"><strong>${g[0]}</strong><p>${g[1]}</p></div><span class="pill ${g[2]?'green':'amber'}">${g[2]?'Verified':'Pending'}</span></li>`).join('');
const filter=$('filter').value,query=$('search').value.toLowerCase();const shown=tests.filter(t=>(filter==='all'||(latest(t.id)?.status||'not-run')===filter)&&(t.title+' '+t.steps+' '+t.criteria).toLowerCase().includes(query));
$('test-list').innerHTML=shown.map(t=>{const result=latest(t.id);return `<article class="test-card"><span class="test-index">${String(tests.indexOf(t)+1).padStart(2,'0')}</span><div><h2>${t.title}</h2><p>${t.steps}</p><p class="criteria"><strong>Pass when:</strong> ${t.criteria}</p>${result?`<div class="observation">${esc(result.note)}</div><small>${esc(result.device)} · ${date(result.at)}</small>`:''}</div><div class="test-actions">${pill(result?.status||'not-run')}<button class="button" data-record="${t.id}">${result?'Record retest':'Record result'}</button></div></article>`}).join('');$('no-matches').hidden=shown.length>0;
$('activity-list').innerHTML=events.length?events.slice().sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).map(x=>`<article class="event"><div class="section-heading"><strong>${tests.find(t=>t.id===x.test).title}</strong>${pill(x.status)}</div><p>${esc(x.note)}</p><small>${esc(x.device)} · ${date(x.at)} · ${x.hash.toLowerCase()===E.build.sha256.toLowerCase()?'Current APK':'Different APK — excluded from current counts'}</small></article>`).join(''):'<p class="empty-observation">No headset observations recorded yet. Installation succeeded; gameplay acceptance remains open.</p>';
}
function route(){const id=location.hash.slice(1)||'overview';const view=['overview','tests','evidence','activity'].includes(id)?id:'overview';document.querySelectorAll('.view').forEach(s=>s.hidden=s.id!==view);document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});window.scrollTo(0,0)}
$('snapshot').textContent='EVIDENCE SNAPSHOT · '+date(E.asOf);$('apk-size').textContent=(E.build.apkBytes/1e6).toFixed(1)+' MB';
const details=[['Engine',E.unity],['Version',E.build.version],['APK size',(E.build.apkBytes/1e6).toFixed(2)+' MB / '+E.build.apkBytes.toLocaleString()+' bytes'],['Build result',E.build.result],['Errors / warnings',E.build.errors+' / '+E.build.warnings],['Build duration','15 min 51 sec'],['Architecture',E.build.architecture],['Signature',E.build.signature],['App ID',E.build.applicationId],['SHA-256',E.build.sha256]];
$('build-details').innerHTML=details.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('');
const features=[['Desktop mouse interaction','Smoke tested'],['Piece selection & animated moves','Smoke tested'],['Two game layouts & reset','Smoke tested'],['Fingertip pinch input','Device test open'],['Spatial anchor save & restore','Device test open'],['Table repositioning & retry','Device test open'],['World-space controls & labels','Device test open']];
$('features').innerHTML=features.map(([a,b])=>`<li><span>${a}</span><span class="pill ${b==='Smoke tested'?'green':'amber'}">${b}</span></li>`).join('');
$('excluded').innerHTML=['Turns & captures','Scoring / win conditions','Multiplayer','Shared anchors','Physical-piece recognition','Automatic surface detection','Saved piece positions'].map(x=>`<span>${x}</span>`).join('');
$('sources').innerHTML=E.sources.map(x=>`<div><strong>${esc(x.name)}</strong><code>${esc(x.path)}</code></div>`).join('');document.querySelector('.mini-board').innerHTML='<i></i>'.repeat(32);
$('filter').addEventListener('change',render);$('search').addEventListener('input',render);window.addEventListener('hashchange',route);
$('test-list').addEventListener('click',event=>{let button=event.target.closest('[data-record]');if(!button)return;activeTest=tests.find(t=>t.id===button.dataset.record);$('dialog-title').textContent=activeTest.title;$('dialog-criteria').textContent=activeTest.criteria;$('result-note').value='';$('result-status').value='pass';$('result-device').value='Quest 3';$('result-dialog').showModal();});
for(const id of ['cancel','cancel-x'])$(id).onclick=()=>$('result-dialog').close();
$('result-form').addEventListener('submit',event=>{event.preventDefault();const note=$('result-note').value.trim(),device=$('result-device').value.trim();if(!note||!device){notice('A written observation and device name are required.');return}events.push({id:crypto.randomUUID(),test:activeTest.id,status:$('result-status').value,note,device,hash:E.build.sha256,at:new Date().toISOString()});save();render();$('result-dialog').close();notice(storageWorks?'Result saved in this browser. Export your log for a backup.':'Result recorded in memory only. Export your log before closing.');});
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({schema:1,project:'living-table',exportedAt:new Date().toISOString(),events},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='living-table-test-log.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);notice('Test log exported. Keep this file to restore or transfer your observations.');};
$('import').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('File is too large (2 MB limit).');const data=JSON.parse(await file.text());if(data.schema!==1||data.project!=='living-table'||!Array.isArray(data.events)||data.events.length>5000||!data.events.every(validEvent))throw Error('This is not a valid Living Table test log.');let added=0;const existing=new Set(events.map(x=>x.id));for(const row of data.events){if(!existing.has(row.id)){events.push(row);existing.add(row.id);added++;}}save();render();notice(`Imported ${added} new observations. Results for different APKs stay in the activity log but do not affect current progress.`);}catch(error){notice('Import rejected: '+error.message)}finally{event.target.value=''}};
$('copy-path').onclick=async()=>{const path='P:\\_GAMES\\Project 26\\Builds\\LivingTable-Quest.apk';try{await navigator.clipboard.writeText(path);notice('Local APK path copied.')}catch(error){notice('Local APK path: '+path)}};
if(!E.build.newerThanRuntime||!E.smoke.newerThanRuntime)notice('Source files are newer than one or more verification results. Rebuild and retest before treating them as current.');
render();route();
// Verification never carries over silently to a different APK.
if(E.installCurrent===false){document.querySelector('.release-stamp .pill').textContent='INSTALLATION NEEDS RECHECK';document.querySelector('.release-stamp .pill').className='pill amber';document.querySelector('.release-stamp small').textContent='Previous build installed Oct 25, 2026';document.querySelector('.heading .intro').textContent='A new APK needs verification and a fresh device installation.';}
if(E.verificationCurrent===false){document.querySelector('.metrics article:nth-child(3) small').textContent='New APK · signature and architecture need recheck';}
document.querySelector('.metrics article:nth-child(4) strong').innerHTML=esc(E.build.errors)+' <em>errors</em>';
$('warning-summary').textContent=E.build.warnings+' warnings recorded; review remains open';

